#!/usr/bin/env bash
# WRF v4.6.1 UW PBL (bl_pbl_physics = 9) column oracle, CPU only.
#
#   run_oracle.sh WRF461_SOURCE_ROOT OUT
#
# WRF461_SOURCE_ROOT is a WRF v4.6.1 tree (a clone at tag v4.6.1); every file
# SOURCES-v4.6.1.sha256 pins is checked before anything compiles.  Writes:
#
#   OUT/cases      the case files: this lane's fresh sweep (make_verify_cases.py,
#                  240 columns) and the 4.7.1 record's own sets regenerated by
#                  their own generators (g35/g44/g61, extra35, sub35: 130 columns)
#   OUT/build      ../uwpbl_wrf471_oracle/build.sh's four variants (pristine
#                  -O0 = the reference, o2 = WRF's stock gfortran flags,
#                  snan, spy) plus a fifth, crlibm: the pristine objects
#                  relinked so cos and acos are the correctly rounded CORE-MATH
#                  functions (crlibm_shim.c), every other libm call unchanged
#   OUT/fixtures   pristine fixtures + indexes; OUT/fixtures-crlibm the crlibm
#                  variant's fixtures
#   OUT/oracle-report.txt   what was compared and what matched
set -euo pipefail
if [[ $# -ne 2 ]]; then
    echo "usage: run_oracle.sh WRF461_SOURCE_ROOT OUT" >&2
    exit 2
fi
src=$(realpath "$1")
out=$(realpath -m "$2")
here=$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)
orc="${here}/../uwpbl_wrf471_oracle"
py=${PYTHON:-python3}
mkdir -p "${out}"
report="${out}/oracle-report.txt"
: > "${report}"
log() { echo "$*" | tee -a "${report}"; }

# ---- cases -------------------------------------------------------------------
cases="${out}/cases"
rm -rf "${cases}" "${out}/cases-tmp"
mkdir -p "${cases}" "${out}/cases-tmp"
"${py}" "${here}/make_verify_cases.py" "${cases}"
"${py}" "${orc}/make_cases.py" "${out}/cases-tmp/rec"
cp "${out}/cases-tmp/rec/"cases-g*.bin "${out}/cases-tmp/rec/cases-index.json" "${cases}/"
"${py}" "${orc}/make_extra_cases.py" "${out}/cases-tmp/extra"
cp "${out}/cases-tmp/extra/cases-extra35.bin" "${cases}/"
cp "${out}/cases-tmp/extra/cases-index.json" "${cases}/cases-extra35-index.json"
"${py}" "${orc}/make_subnormal_cases.py" "${out}/cases-tmp/sub"
cp "${out}/cases-tmp/sub/cases-sub35.bin" "${out}/cases-tmp/sub/cases-sub35.bin.step2" \
   "${out}/cases-tmp/sub/cases-sub35-index.json" "${cases}/"
rm -rf "${out}/cases-tmp"
( cd "${cases}" && sha256sum ./*.bin ./*.step2 > SHA256SUMS )
log "cases: $(ls "${cases}"/cases-*.bin | wc -l) files"

# ---- the four build.sh variants on the v4.6.1 sources ------------------------
set +e
UWPBL_SOURCES_PINS="${here}/SOURCES-v4.6.1.sha256" \
    bash "${orc}/build.sh" "${src}" "${out}/build" "${cases}" > "${out}/build.log" 2>&1
status=$?
set -e
log "build.sh exit status ${status}"
grep -E 'byte-identical|DIFFERS|FAIL' "${out}/build.log" >> "${report}" || true

# ---- crlibm variant ------------------------------------------------------------
cr="${out}/build/crlibm"
rm -rf "${cr}"
mkdir -p "${cr}"
(
    cd "${cr}"
    gcc -O2 -ffp-contract=off -c "${orc}/libm64/upstream/cos.c" -o cr_cos.o
    gcc -O2 -ffp-contract=off -c "${orc}/libm64/upstream/acos.c" -o cr_acos.o
    gcc -O2 -ffp-contract=off -fno-builtin -c "${here}/crlibm_shim.c" -o crlibm_shim.o
    objs=()
    for o in "${out}"/build/pristine/*.o; do
        case "$(basename "${o}")" in run_stage_*) continue ;; esac
        objs+=("${o}")
    done
    gfortran -o run_camuwpbl_cr "${objs[@]}" crlibm_shim.o cr_cos.o cr_acos.o
    nm run_camuwpbl_cr | grep -E ' T (cos|acos)$' > interposed-symbols.txt
    [[ $(wc -l < interposed-symbols.txt) -eq 2 ]] || { echo "cos/acos not defined in run_camuwpbl_cr" >&2; exit 8; }
    gcc -O0 -fno-builtin -c "${here}/crlibm_control.c" -o crlibm_control.o
    gcc -o crlibm_control crlibm_control.o crlibm_shim.o cr_cos.o cr_acos.o -lm -ldl
    ./crlibm_control > control.txt
)
log "crlibm positive control: $(tail -1 "${cr}/control.txt")"
mkdir -p "${out}/fixtures-crlibm"
for c in "${cases}"/cases-*.bin; do
    stem=$(basename "${c}" .bin)
    ( cd "${cr}" && ./run_camuwpbl_cr "${c}" "${cr}/${stem}" )
    cp "${cr}/${stem}.bin" "${cr}/${stem}.manifest" "${out}/fixtures-crlibm/"
    if cmp -s "${cr}/${stem}.bin" "${out}/build/pristine/${stem}.bin"; then
        log "${stem}: crlibm variant byte-identical to the host-libm reference"
    else
        log "${stem}: crlibm variant DIFFERS from the host-libm reference (cos/acos rounding reached an output)"
    fi
done

# ---- cos/acos census: host-libm results, every call also compared with CR -------
(
    cd "${cr}"
    gcc -O2 -ffp-contract=off -fno-builtin -c "${here}/libm_census.c" -o libm_census.o
    objs=()
    for o in "${out}"/build/pristine/*.o; do
        case "$(basename "${o}")" in run_stage_*) continue ;; esac
        objs+=("${o}")
    done
    gfortran -o run_camuwpbl_census "${objs[@]}" libm_census.o cr_cos.o cr_acos.o -ldl
)
for c in "${cases}"/cases-*.bin; do
    stem=$(basename "${c}" .bin)
    line=$( cd "${cr}" && ./run_camuwpbl_census "${c}" "${cr}/${stem}-census" 2>&1 >/dev/null | grep '^libm-census' )
    if cmp -s "${cr}/${stem}-census.bin" "${out}/build/pristine/${stem}.bin"; then
        log "${stem}: ${line} (outputs byte-identical to the reference)"
    else
        log "${stem}: ${line} (census build outputs DIFFER from the reference: census invalid)"
        status=9
    fi
    rm -f "${cr}/${stem}-census.bin" "${cr}/${stem}-census.manifest"
done

# ---- fixtures ----------------------------------------------------------------
mkdir -p "${out}/fixtures"
cp "${out}/build/fixtures/"cases-*.bin "${out}/build/fixtures/"cases-*.manifest \
   "${out}/build/fixtures/toolchain.txt" "${out}/fixtures/"
rm -f "${out}/fixtures/"*-spy.bin "${out}/fixtures/"*-spy.manifest
cp "${cases}/"*index.json "${out}/fixtures/"
( cd "${out}/fixtures" && sha256sum ./*.bin ./*.manifest > SHA256SUMS )
( cd "${out}/fixtures-crlibm" && sha256sum ./*.bin ./*.manifest > SHA256SUMS )
cat "${out}/build/libm-report.txt" >> "${report}"
log "fixtures: ${out}/fixtures (pristine), ${out}/fixtures-crlibm"
exit "${status}"
